#include <iostream>
using namespace std;

int main() {
    int llama;
    llama = 10;

    auto nullptr_variable = nullptr;
    auto null_pointer_variable = nullptr;

    cout << "Llama is " << llama << endl;

    cout << "nullptr_variable is " << nullptr_variable << endl;
    cout << "null_pointer_variable is " << null_pointer_variable << endl;

    return 0;
}
```
